@section('js')
<script>
document.addEventListener('DOMContentLoaded', function () {
    var csrf = document.querySelector('meta[name="csrf-token"]').content;
    var previewUrl = @json(route('admin.moodle-sync.preview'));
    var startUrl = @json(route('admin.moodle-sync.start'));
    var testUrl = @json(route('admin.moodle-sync.test'));
    var progressUrl = @json(route('admin.moodle-sync.progress', ['run' => '__RUN__']));
    var labels = {users:'user siswa dan GTK', cohorts:'kohor rombel', categories:'kategori kursus', all:'seluruh data'};
    var formatNumber = function (value) { return new Intl.NumberFormat('id-ID').format(value || 0); };
    var notify = function (type, message) { if (window.toastr && typeof window.toastr[type] === 'function') window.toastr[type](message); else window.alert(message); };
    var post = function (url, body) { return fetch(url, {method:'POST', headers:{'Content-Type':'application/json', 'Accept':'application/json', 'X-CSRF-TOKEN':csrf}, body:JSON.stringify(body || {})}).then(function (response) { return response.json().then(function (data) { if (!response.ok) throw new Error(data.message || 'Permintaan gagal.'); return data; }); }); };
    var modal = function (options) { return window.Swal ? window.Swal.fire(options) : Promise.resolve({isConfirmed:window.confirm(options.text || options.title || 'Lanjutkan?')}); };
    var progressHtml = function (title, stage, percent, log) { return '<div class="live-stage mb-2">'+stage+'</div><div class="progress mb-2"><div class="progress-bar" style="width:'+percent+'%">'+percent+'%</div></div><div class="live-count small text-muted">0 item</div><div class="live-log mt-3">['+percent+'%] '+log+'</div>'; };
    var updateProgress = function (data) { var box = window.Swal && window.Swal.getHtmlContainer ? window.Swal.getHtmlContainer() : null; if (!box) return; var bar=box.querySelector('.progress-bar'), stage=box.querySelector('.live-stage'), count=box.querySelector('.live-count'), log=box.querySelector('.live-log'); if(bar){bar.style.width=data.percent+'%';bar.textContent=data.percent+'%';} if(stage)stage.textContent=data.stage || 'Memproses'; if(count)count.textContent=formatNumber(data.processed)+' / '+formatNumber(data.total)+' item'; if(log)log.innerHTML='['+data.percent+'%] '+(data.stage || 'Memproses')+'<br>'+log.innerHTML; };
    var runProgress = function (runId) { fetch(progressUrl.replace('__RUN__', runId), {headers:{'Accept':'application/json'}}).then(function (response) { return response.json(); }).then(function (data) { updateProgress(data); if (data.status === 'success' || data.status === 'failed') { if(window.Swal) window.Swal.close(); notify(data.status === 'success' ? 'success' : 'error', data.status === 'success' ? 'Sinkronisasi selesai.' : (data.error || 'Sinkronisasi gagal.')); setTimeout(function(){window.location.reload();}, 700); return; } setTimeout(function(){runProgress(runId);}, 1500); }).catch(function(){setTimeout(function(){runProgress(runId);}, 2500);}); };
    var startSync = function (type, token) { return post(startUrl, {type:type, preview_token:token, confirmed:true}).then(function (data) { if(window.Swal) window.Swal.fire({title:'Sinkronisasi berjalan', html:progressHtml('Sinkronisasi', 'Menunggu worker Moodle', 0, 'Sinkronisasi masuk antrean'), allowOutsideClick:false, showConfirmButton:false}); runProgress(data.run_id); }); };

    document.getElementById('moodle-test-connection').addEventListener('click', function () { modal({icon:'question', title:'Tes koneksi Moodle?', text:'Sistem akan menghubungi Moodle tanpa mengubah data.', showCancelButton:true, confirmButtonText:'Ya, tes koneksi', cancelButtonText:'Batal', confirmButtonColor:'#2563eb'}).then(function(result){ if(!result.isConfirmed) return; if(window.Swal) window.Swal.fire({title:'Menguji koneksi Moodle', html:progressHtml('Tes koneksi', 'Menghubungi Web Service Moodle', 25, 'Permintaan dikirim'), allowOutsideClick:false, showConfirmButton:false}); return post(testUrl).then(function(data){ if(window.Swal) window.Swal.fire({icon:'success', title:'Koneksi berhasil', html:progressHtml('Tes koneksi', data.message, 100, data.message), confirmButtonText:'Tutup'}); else notify('success', data.message); }).catch(function(error){ if(window.Swal) window.Swal.fire({icon:'error', title:'Tes koneksi gagal', html:progressHtml('Tes koneksi', error.message, 100, error.message), confirmButtonText:'Tutup'}); else notify('error', error.message); }); }); });
    document.querySelectorAll('.sync-preview').forEach(function(button){ button.addEventListener('click', function(){ var type=button.dataset.type; if(window.Swal) window.Swal.fire({title:'Menyiapkan preview read-only', html:progressHtml('Perbandingan', 'Membaca SIMANSA dan Moodle', 10, 'Belum ada perubahan yang dilakukan'), allowOutsideClick:false, showConfirmButton:false}); post(previewUrl, {type:type}).then(function(data){ var p=data.preview, a=data.actions; var comparison=' <div class="alert alert-success mt-3"><strong>Preview read-only</strong><br>Perubahan aktual belum dilakukan. Moodle hanya akan ditulis setelah persetujuan checkbox.</div>'; var html='<div class="row text-center"><div class="col-6"><strong class="d-block h4">'+formatNumber(p.students)+'</strong><small>Siswa SIMANSA</small></div><div class="col-6"><strong class="d-block h4">'+formatNumber(p.gtk)+'</strong><small>GTK SIMANSA</small></div><div class="col-6"><strong class="d-block h4">'+formatNumber(p.cohorts)+'</strong><small>Kohor</small><small class="d-block text-muted">'+formatNumber(p.members)+' anggota</small></div><div class="col-6"><strong class="d-block h4">'+formatNumber(p.category_items)+'</strong><small>Item kategori</small></div></div><div class="alert alert-warning mt-3 text-left"><strong>Rencana perubahan di Moodle</strong><br>Tambah: <b>'+formatNumber(a.create)+'</b> &nbsp; Ubah: <b>'+formatNumber(a.update)+'</b> &nbsp; Tambah anggota: <b>'+formatNumber(a.membership_add)+'</b><br>Tidak berubah: <b>'+formatNumber(a.unchanged)+'</b><br><small>Anggota ekstra di Moodle tidak dihapus.</small></div>'+comparison; return modal({icon:'info', title:'Preview '+labels[type], html:html, text:'Lanjutkan ke konfirmasi sinkronisasi?', showCancelButton:true, confirmButtonText:'Lanjutkan', cancelButtonText:'Batal', confirmButtonColor:'#2563eb'}).then(function(result){ if(!result.isConfirmed) return null; if(!data.comparison_complete) { notify('error', 'Preview membership belum lengkap; sinkronisasi diblokir.'); return null; } var check='<div class="text-left"><p>Preview sudah dibandingkan dengan Moodle. Data akan dibuat/diperbarui sesuai rencana di atas.</p><label style="cursor:pointer"><input id="moodle-confirm-checkbox" type="checkbox" style="margin-right:8px"> Saya setuju menjalankan perubahan ini ke Moodle.</label></div>'; return modal({icon:'warning', title:'Konfirmasi final', html:check, showCancelButton:true, confirmButtonText:'Ya, mulai', cancelButtonText:'Batal', confirmButtonColor:'#2563eb', focusConfirm:false, didOpen:function(){ var confirmButton=window.Swal.getConfirmButton(); confirmButton.disabled=true; document.getElementById('moodle-confirm-checkbox').addEventListener('change', function(){ confirmButton.disabled=!this.checked; }); }, preConfirm:function(){ var checkbox=document.getElementById('moodle-confirm-checkbox'); if(!checkbox || !checkbox.checked){ window.Swal.showValidationMessage('Centang persetujuan sebelum memulai.'); return false; } return true; }}).then(function(confirm){ return confirm.isConfirmed ? startSync(type, data.preview_token) : null; }); }); }).catch(function(error){ if(window.Swal) window.Swal.fire({icon:'error', title:'Preview gagal', text:error.message}); else notify('error', error.message); }); }); });
});
</script>
